#[derive(Debug, Clone, Copy)]
pub(super) enum DataType {
    None,
    Byte,
    Short,
    UShort,
    Int,
    UInt,
    Float,
    Double,
    IVec2,
    IVec3,
    IVec4,
    Vec2,
    Vec3,
    Vec4,
    Mat2,
    Mat3,
    Mat3x4,
    Mat4x3,
    Mat4,
    Bool,
    String,
    Path,
    FixedString,
    LsString,
    ULongLong,
    ScratchBuffer,
    Long,
    Int8,
    TranslatedString,
    WString,
    LsWString,
    Uuid,
    Int64,
    TranslatedFsString,
}

impl DataType {
    pub(super) const fn from_lower_six_bits(value: u32) -> Self {
        match value & 0b11_1111_u32 {
            1 => Self::Byte,
            2 => Self::Short,
            3 => Self::UShort,
            4 => Self::Int,
            5 => Self::UInt,
            6 => Self::Float,
            7 => Self::Double,
            8 => Self::IVec2,
            9 => Self::IVec3,
            10 => Self::IVec4,
            11 => Self::Vec2,
            12 => Self::Vec3,
            13 => Self::Vec4,
            14 => Self::Mat2,
            15 => Self::Mat3,
            16 => Self::Mat3x4,
            17 => Self::Mat4x3,
            18 => Self::Mat4,
            19 => Self::Bool,
            20 => Self::String,
            21 => Self::Path,
            22 => Self::FixedString,
            23 => Self::LsString,
            24 => Self::ULongLong,
            25 => Self::ScratchBuffer,
            26 => Self::Long,
            27 => Self::Int8,
            28 => Self::TranslatedString,
            29 => Self::WString,
            30 => Self::LsWString,
            31 => Self::Uuid,
            32 => Self::Int64,
            33 => Self::TranslatedFsString,
            _ => Self::None,
        }
    }

    pub(super) const fn as_u32(self) -> u32 {
        match self {
            Self::None => 0,
            Self::Byte => 1,
            Self::Short => 2,
            Self::UShort => 3,
            Self::Int => 4,
            Self::UInt => 5,
            Self::Float => 6,
            Self::Double => 7,
            Self::IVec2 => 8,
            Self::IVec3 => 9,
            Self::IVec4 => 10,
            Self::Vec2 => 11,
            Self::Vec3 => 12,
            Self::Vec4 => 13,
            Self::Mat2 => 14,
            Self::Mat3 => 15,
            Self::Mat3x4 => 16,
            Self::Mat4x3 => 17,
            Self::Mat4 => 18,
            Self::Bool => 19,
            Self::String => 20,
            Self::Path => 21,
            Self::FixedString => 22,
            Self::LsString => 23,
            Self::ULongLong => 24,
            Self::ScratchBuffer => 25,
            Self::Long => 26,
            Self::Int8 => 27,
            Self::TranslatedString => 28,
            Self::WString => 29,
            Self::LsWString => 30,
            Self::Uuid => 31,
            Self::Int64 => 32,
            Self::TranslatedFsString => 33,
        }
    }
}
